div.script:
const urlParams = new URLSearchParams(window.location.search);

window.EJS_player = '#game';
window.EJS_core = urlParams.get('core');
window.EJS_gameUrl = urlParams.get('game');
window.EJS_pathtodata = 'https://cdn.jsdelivr.net/gh/greeniYT/4.3.0@main/EmulatorJS-4.3.0-pre/data/';
window.EJS_color = urlParams.get('color') || '#107c10'; 
window.EJS_startOnLoaded = true;
window.EJS_threads = true;
window.EJS_gameID = urlParams.get('game');
window.EJS_fullscreenOnLoad = false;
